	const agent = new Agent({
		initialState: {
			systemPrompt,
			model: initialModel as any, // Can be null in interactive mode
			thinkingLevel: initialThinking,
			tools: selectedTools,
		},
		messageTransformer,
		queueMode: settingsManager.getQueueMode(),
		transport: new ProviderTransport({
